#!/bin/bash
# Register wapt-webconsole as an OpenID Connect client of Authelia (file configuration, Docker container),
# and optionally add a user to a role group of the users file. Run as root on the Authelia host.
#
#   ./authelia-register.sh --config /opt/authelia/config/configuration.yml \
#       --redirect https://wwc.example.org/auth/callback --secret-out ./secrets/oidc_client_secret \
#       [--users /opt/authelia/config/users_database.yml --user alice --group wapt-admins] [--container authelia]
#
# The client secret is generated by Authelia itself (--random): it is written to --secret-out only, never
# printed nor passed on a command line. Both files are backed up first; the configuration is validated, then
# the container restarted (the users file is reloaded by Authelia when "watch: true").
set -euo pipefail

container=authelia users="" user="" group="wapt-admins" cfg="" redirect="" secret_out=""
while [ $# -gt 0 ]; do
    case "$1" in
        --config) cfg=$2; shift 2 ;;
        --redirect) redirect=$2; shift 2 ;;
        --secret-out) secret_out=$2; shift 2 ;;
        --users) users=$2; shift 2 ;;
        --user) user=$2; shift 2 ;;
        --group) group=$2; shift 2 ;;
        --container) container=$2; shift 2 ;;
        *) echo "unknown option $1" >&2; exit 2 ;;
    esac
done
[ -n "$cfg" ] && [ -n "$redirect" ] && [ -n "$secret_out" ] || { sed -n '2,9p' "$0"; exit 2; }
grep -q "client_id: wapt-webconsole" "$cfg" && { echo "wapt-webconsole is already a client in $cfg" >&2; exit 1; }
grep -q "^ *clients:" "$cfg" || { echo "no identity_providers.oidc.clients list in $cfg: add the client by hand" >&2; exit 1; }

ts=$(date +%Y%m%d-%H%M%S)
cp -p "$cfg" "$cfg.bak-$ts"
echo "backup: $cfg.bak-$ts"
[ -n "$users" ] && cp -p "$users" "$users.bak-$ts" && echo "backup: $users.bak-$ts"

# 1. Client secret, generated and hashed by Authelia
out=$(docker exec "$container" authelia crypto hash generate pbkdf2 --variant sha512 \
      --random --random.length 64 --random.charset alphanumeric)
install -d -m 700 "$(dirname "$secret_out")"
( umask 077; printf '%s' "$(printf '%s\n' "$out" | sed -n 's/^Random Password: //p')" > "$secret_out" )
digest=$(printf '%s\n' "$out" | sed -n 's/^Digest: //p')
unset out
[ -s "$secret_out" ] && [ -n "$digest" ] || { echo "secret generation failed" >&2; exit 1; }
echo "client secret written to $secret_out"

# 2. Client, appended to the clients list (assumed to be the last block of the file, as in the default layout)
tail -c1 "$cfg" | od -An -c | grep -q '\\n' || echo >> "$cfg"
cat >> "$cfg" <<EOF
      - client_id: wapt-webconsole
        client_name: "WAPT Console"
        client_secret: '$digest'
        public: false
        authorization_policy: two_factor
        consent_mode: implicit
        require_pkce: true
        pkce_challenge_method: S256
        redirect_uris:
          - $redirect
        scopes: [openid, profile, email, groups]
        response_types: [code]
        grant_types: [authorization_code]
        token_endpoint_auth_method: client_secret_basic
EOF

# 3. Role group for a user of the users file
if [ -n "$users" ] && [ -n "$user" ]; then
    python3 - "$users" "$user" "$group" <<'PY'
import re, sys
path, user, group = sys.argv[1:]
lines = open(path).read().split("\n")
start = next(i for i, l in enumerate(lines) if re.fullmatch(rf"  {re.escape(user)}:\s*", l))
end = next((i for i in range(start + 1, len(lines)) if re.match(r"  \S", lines[i]) or not lines[i].startswith(" ")),
           len(lines))
g = next(i for i in range(start, end) if lines[i].strip() == "groups:")
items = [i for i in range(g + 1, end) if lines[i].strip().startswith("- ")]
if any(lines[i].strip() == f"- {group}" for i in items):
    sys.exit(0)
indent = lines[items[0]].split("-")[0] if items else " " * 6
lines.insert((items[-1] if items else g) + 1, f"{indent}- {group}")
open(path, "w").write("\n".join(lines))
PY
    echo "--- $users"; diff "$users.bak-$ts" "$users" || true
fi

echo "--- $cfg (secret masked)"
diff "$cfg.bak-$ts" "$cfg" | sed "s/client_secret: .*/client_secret: <masked>/" || true

# 4. Validate, then restart; restore the backups if the configuration is refused
if ! docker exec "$container" authelia validate-config --config /config/configuration.yml; then
    echo "invalid configuration: backups restored" >&2
    cp -p "$cfg.bak-$ts" "$cfg"; [ -n "$users" ] && cp -p "$users.bak-$ts" "$users"
    exit 1
fi
docker restart "$container" >/dev/null
echo "Authelia restarted"
